SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"treatment_regimen\", \"name_of_ici\", \"class_of_ici\", \"cancer_type\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 3' AND \"cancer_type\" = 'Colorectal' AND \"class_of_ici\" = 'PD1' AND \"type_of_combination\" = 'monotherapy' AND \"type_of_therapy\" = 'immunotherapy' ORDER BY \"year\" DESC;